timeout 900 python - <<'EOF' 2>&1 | grep -v "warn" | tail -30
import sys; sys.path.insert(0,'/app')
import convert_data as cd
from brainbox.io.one import SessionLoader
one = cd.get_one()
eids = [l.strip() for l in open('/tmp/failed_eids.txt')][:6]
for eid in eids:
    sl = SessionLoader(one=one, eid=eid)
    msgs=[]
    for view,key in (('left','leftCamera'),('right','rightCamera')):
        try:
            sl.load_motion_energy(views=[view]); msgs.append(f'{view}: OK {sl.motion_energy[key].shape}')
        except Exception as e:
            msgs.append(f'{view}: {type(e).__name__} {str(e)[:120]}')
    # what datasets exist?
    try:
        dsets = [d for d in one.list_datasets(eid) if 'MotionEnergy' in d or 'Camera.times' in d]
    except Exception as e:
        dsets = [f'list err {e}']
    print(eid, '|', ' ; '.join(msgs), '|', dsets[:6])
EOF

