arguments.command:
timeout 900 python - <<'EOF' 2>&1 | grep -v warn | tail -20
import sys, numpy as np; sys.path.insert(0,'/app')
import convert_data as cd
from brainbox.io.one import SessionLoader
one = cd.get_one(); eid='f8041c1e-5ef4-4ae6-afec-ed82d7a74dc1'
sl = SessionLoader(one=one, eid=eid)
tr, mask = cd.load_trials_and_mask(sl)
print('trials', len(tr), 'pass trial QC', mask.sum())
at = tr['stimOn_times'].to_numpy(); at=np.where(np.isnan(at),0.,at)
begs, ends = at-0.5, at+1.5
for name in ['wheel-speed','whisker-motion-energy']:
    try:
        t,v = cd.load_behavior_trace(sl,name)
        b,ok = cd.bin_behavior(t,v,begs,ends)
        print(name,'n',len(v),'nanfrac',np.mean(~np.isfinite(v)),'ok trials',ok.sum(),'span',t[[0,-1]], 'trial span', at.min(), at.max())
    except Exception as e: print(name,'FAIL',e)
for view,key in (('left','leftCamera'),('right','rightCamera')):
    try:
        sl.load_motion_energy(views=[view]); me=sl.motion_energy[key]
        print(view, me.shape, 'nan', np.mean(~np.isfinite(me['whiskerMotionEnergy'].to_numpy())), me['times'].to_numpy()[[0,-1]])
    except Exception as e: print(view,'fail',type(e).__name__)
EOF

